const GLOSSARY = [
 ['AI accelerator / NPU','Phones','A specialised processor designed to speed up certain machine-learning tasks. The app must support it to benefit.'],
 ['AMOLED / OLED','Phones','A display technology where pixels emit their own light, enabling very deep blacks.'],
 ['Benchmark','Phones / PC','A repeatable test used to compare performance. Scores are useful only when the test and conditions are comparable.'],
 ['Bluetooth','Phones / PC','Short-range wireless communication commonly used by headphones, keyboards and other accessories.'],
 ['CPU','Phones / PC','Central processing unit; executes general instructions and coordinates much of a computer’s work.'],
 ['eSIM','Phones','An electronic SIM profile that can be provisioned without inserting a traditional removable SIM card.'],
 ['FPS','PC / Cars','In graphics, frames per second. In cars, the abbreviation can also mean something else, so use context.'],
 ['GPU','Phones / PC','Graphics processing unit; handles graphics and many parallel computing tasks.'],
 ['HDR','Phones / PC','High dynamic range imaging/display: techniques and standards for representing a wider range of brightness. Quality varies.'],
 ['Hz','Phones / PC','Hertz, or cycles per second. For a screen, refresh rate is how often it can update per second.'],
 ['IMEI','Phones','An identifier for cellular equipment. Keep it private and share only with trusted official support when needed.'],
 ['IP rating','Phones','A code describing tested protection against ingress of solids/dust and water under specified conditions.'],
 ['ISP','Phones','Image signal processor; helps convert raw camera-sensor information into a finished photo or video.'],
 ['mAh','Phones','Milliampere-hour; a measure of electric charge capacity, not by itself a direct battery-runtime score.'],
 ['Megapixel (MP)','Phones','One million image pixels. Pixel count does not fully determine camera quality.'],
 ['NFC','Phones','Near-field communication; very short-range wireless communication used for supported tap-style tasks.'],
 ['NVMe','PC','A storage protocol commonly used by SSDs connected over PCI Express.'],
 ['PCIe','PC','A high-speed serial expansion interface used by GPUs, SSDs and other devices.'],
 ['PSU','PC','Power supply unit; converts wall AC power to the DC power needed by computer components.'],
 ['RAM','Phones / PC','Fast, temporary working memory for data that apps and the operating system are currently using.'],
 ['Refresh rate','Phones / PC','How often a screen can update, typically described in Hz. The source must also provide frames/content.'],
 ['SoC','Phones','System-on-a-chip; an integrated package that combines several computing and communication components.'],
 ['SSD','PC','Solid-state drive: persistent storage using flash memory, with no spinning disks.'],
 ['TDP','PC','A design/thermal power guideline defined differently by vendors; it is not always the system’s maximum power draw.'],
 ['USB-C','Phones / PC','A reversible connector shape. Data speed, display output and charging features vary by port and device.'],
 ['VRAM','PC','Memory used by a GPU for graphics data such as textures and frame buffers.'],
 ['Watt (W)','Phones / PC / Cars','A unit of power—the rate of energy transfer or work.'],
 ['kWh','Cars','Kilowatt-hour, a unit of energy used when discussing EV battery capacity and electricity consumption.'],
 ['kW','Cars','Kilowatt, a unit of power. Do not confuse kW (power) with kWh (energy).'],
 ['Torque','Cars','A turning effect, commonly expressed in newton-metres (Nm).'],
 ['Horsepower / bhp','Cars','A unit used to express power output. It is related to torque and rotational speed, but is not the same thing as torque.'],
 ['RPM','Cars','Rotations per minute; often used to describe engine or motor rotational speed.'],
 ['ABS','Cars','Anti-lock braking system; helps prevent the wheels from locking under braking and can help preserve steering control.'],
 ['ESC','Cars','Electronic stability control; may help the driver maintain directional control in some situations.'],
 ['Regenerative braking','Cars','A system that recovers some energy during slowing and returns it to the battery in an electrified vehicle.'],
 ['Wheelbase','Cars','The distance between the centres of the front and rear axles.'],
 ['Ground clearance','Cars','The distance between a defined low point of a vehicle and the ground, under specified conditions.'],
 ['Depreciation','Cars','The loss of a vehicle’s value over time. It affects total ownership cost.'],
 ['Crumple zone','Cars','A part of vehicle structure designed to deform in a controlled way and manage crash energy.'],
 ['ADAS','Cars','Advanced driver-assistance systems, such as supported lane, braking or cruise assistance features. Their limits and driver responsibilities matter.']
];

