const pcCourse = COURSES.find(c=>c.id==='pc');
pcCourse.lessons.splice(8,0,{title:'Networking, Wi‑Fi and PC setup',level:'Advanced',mins:15,desc:'Ethernet, Wi‑Fi bands, routers, Bluetooth adapters and home-network basics.',intro:'A PC gets online through a network adapter. Ethernet uses a cable; Wi‑Fi connects wirelessly to an access point/router. The router often connects your home network to an internet service provider, but a local network can still work when the internet is down.',analogy:'A home network is like an apartment building: your device is one flat, the router is the front desk directing messages, and the internet provider is the road connecting the building to other places.',sections:[{title:'Wi‑Fi, Ethernet and Bluetooth',body:'Ethernet can offer stable, low-latency connections when cabling is practical. Wi‑Fi offers flexibility but shares radio spectrum with other devices and walls can weaken signals. Bluetooth is designed mainly for short-range peripherals, not as the ordinary main internet link.',bullets:['2.4 GHz Wi‑Fi generally reaches farther but can be more congested.','5 GHz and 6 GHz Wi‑Fi can offer more capacity at shorter practical ranges, depending on walls and devices.','Wi‑Fi generations, router capabilities, client adapters and internet plan all affect speed.','A faster internet plan cannot fix poor Wi‑Fi coverage by itself.']},{title:'Diagnose slow internet',body:'Compare one device with another, test close to the router, try Ethernet if possible, check outages and distinguish local Wi‑Fi speed from internet speed. Place the router openly and securely; keep its firmware and password up to date.'}],diagram:[['💻','PC adapter','Sends / receives'],['📶','Router/AP','Local network'],['🧱','Walls + noise','Signal loss'],['🌐','ISP','Internet route']],example:{title:'Fast check',body:'If a wired computer is fast but a laptop on the far side of the home is slow, the bottleneck may be Wi‑Fi coverage—not the ISP or CPU.'},myth:'“A Wi‑Fi 6/7 label guarantees a fast internet connection.” Both devices, signal conditions, router setup, congestion and internet service affect real speed.',takeaways:['Ethernet and Wi‑Fi are both useful; the best depends on the setup.','Router placement and interference matter.','Separate local wireless problems from internet-provider problems.'],quiz:[{q:'What is the usual role of a router in a home network?',options:['Connects local devices and routes traffic toward networks/internet','Adds RAM to the PC','Stores every file permanently','Replaces the monitor'],answer:0,why:'A router directs traffic between networks; many home units also contain a Wi‑Fi access point.'},{q:'If Ethernet is fast but far-room Wi‑Fi is slow, investigate first…',options:['Wireless coverage and interference','CPU brand colour','SSD capacity','Monitor refresh rate'],answer:0,why:'The difference points toward wireless signal/coverage or interference.'},{q:'Does the newest Wi‑Fi label guarantee top speed?',options:['Yes, always','No; clients, router, range, interference and internet plan matter','Only if the keyboard is wired','Only for cars'],answer:1,why:'Actual throughput depends on the whole network path and the environment.'}]});
pcCourse.lessons.push({title:'Upgrades, benchmarks and balanced builds',level:'Expert',mins:18,desc:'Find bottlenecks, compare test results and plan upgrades without wasting money.',intro:'A bottleneck is the part that limits performance for a particular task. It can change from one workload or setting to another. A benchmark is only valuable when it resembles your workload and uses comparable conditions.',analogy:'A school relay team is only as fast as the hand-offs and runner strengths across the race. Replacing the fastest runner’s shoes may not improve the team if another leg is the actual bottleneck.',sections:[{title:'Upgrade by evidence',body:'Record what feels slow, measure CPU/GPU/RAM/storage usage and temperature during the specific task, then identify a likely limit. A gaming GPU bottleneck at high resolution differs from a browser that is waiting on a network connection.',bullets:['Before upgrading, check temperatures, background apps, storage space and driver status.','Compare benchmarks at the same resolution, settings, software version and power conditions.','Check the upgrade’s compatibility and likely real-world improvement.','Avoid buying a component because a friend or influencer has different needs.']},{title:'Make a balanced plan',body:'Set budget, intended apps, monitor resolution/refresh, noise needs, upgrade horizon and local pricing. Reserve money for a suitable PSU, cooling, storage, peripherals and legitimate software—not only the headline CPU/GPU.'}],diagram:[['🎯','Define task','What is slow?'],['📊','Measure','Usage + temps'],['🧩','Identify limit','Task-specific'],['💸','Upgrade','Cost vs benefit'],['✅','Verify','Repeat test']],example:{title:'Example',body:'If a game is GPU-limited at your target resolution, a faster GPU may help. If the game is CPU-limited at low resolution, a GPU upgrade alone may give little gain.'},myth:'“A benchmark ranking predicts every real app.” Different workloads use parts differently; compare tests close to your needs.',takeaways:['Bottlenecks are workload-specific.','Measure before buying; test again after upgrading.','Budget for a complete reliable system.'],quiz:[{q:'What is a bottleneck?',options:['The component/resource limiting a particular task','A kind of motherboard screw','The fastest part in every situation','A Wi‑Fi password'],answer:0,why:'The limiting resource depends on the specific workload and configuration.'},{q:'How should you compare benchmarks?',options:['Same conditions and workload where possible','Different resolutions with no labels','Only compare box prices','Choose the most dramatic chart'],answer:0,why:'Comparable conditions are necessary for meaningful results.'},{q:'What is the smartest upgrade process?',options:['Measure, identify the bottleneck, check compatibility, then upgrade','Always buy the most expensive part first','Replace every component at once without testing','Ignore the PSU'],answer:0,why:'Evidence-led upgrades target the actual limitation and avoid compatibility surprises.'}]});
const carCourse = COURSES.find(c=>c.id==='cars');
carCourse.lessons.push({title:'Maintenance, documents and ownership safety',level:'Expert',mins:18,desc:'Build a maintenance calendar and understand the important paperwork.',intro:'Owning a car includes preventing problems, keeping records and making sure the vehicle is legal and safe to use. Exact requirements and renewal timelines can vary by state, vehicle type and current rules, so verify them through official transport/insurer/manufacturer channels.',analogy:'Maintenance is like brushing your teeth and keeping school notes: small regular habits reduce avoidable emergencies and help you prove what has been done.',sections:[{title:'Routine maintenance',body:'Follow the owner’s manual for oil/filters where applicable, fluids, brakes, tyres, battery, lights, wipers, air-conditioning and scheduled inspections. The right interval depends on model, usage and manufacturer guidance; severe traffic, dust, heat or short trips may affect service needs.',bullets:['Check tyre pressure against the manufacturer’s recommended cold pressure.','Pay attention to brake feel/noise, warning lights, leaks, overheating and unusual vibration.','Keep service bills and records, including replaced parts and warranty work.','Do not work under a car supported only by a jack; serious injury can result.']},{title:'Documents and road readiness',body:'Common ownership records can include registration certificate (RC), valid insurance, a valid pollution-under-control (PUC) certificate where required, tax/permit documents for applicable vehicle types and service records. Verify current requirements for your state and vehicle on official channels. Do not rely on hearsay for legal deadlines.',bullets:['Check insurance coverage, exclusions, renewal date and claim process.','Understand what roadside assistance covers and how to contact official help.','Keep emergency contacts and vehicle details safely accessible, without publishing private identifiers.','For tyre changes or breakdowns, stop in a safe place away from moving traffic and follow the owner manual.']},{title:'A preventive routine',body:'Set reminders based on the manual and odometer. Before a longer trip, check tyres, lights, wipers, fluids, documents and charging/fuel plan. Investigate warning signs early instead of driving on and hoping they disappear.'}],diagram:[['📘','Owner manual','Correct schedule'],['🛞','Safety checks','Tyres / brakes / lights'],['🧾','Documents','Valid + available'],['🛠️','Service record','Evidence + resale'],['🛣️','Trip ready','Plan + inspect']],example:{title:'Before a road trip',body:'Check tyre condition and pressure, lamps, wipers, fluid/warning indicators, insurance and relevant documents; confirm your route’s fuel or charging options.'},myth:'“If a car is driving normally, maintenance can wait.” Some faults are not immediately obvious; use the prescribed schedule and respond to warning signs.',takeaways:['Follow the exact vehicle’s owner manual.','Keep legal documents and service history in order.','Safety checks are preventive—not a replacement for professional service.'],quiz:[{q:'Where should the correct maintenance schedule come from?',options:['The exact vehicle owner manual/manufacturer guidance','A random comment for a different model','The radio settings','Only the tyre brand advert'],answer:0,why:'Service intervals and fluids vary by model and usage; the maker’s manual is the starting point.'},{q:'Which is a sensible pre-trip check?',options:['Tyres, lights, wipers, fluids/warnings and relevant documents','Only the car’s colour','Only the music playlist','Ignore any warning lamp'],answer:0,why:'Basic readiness checks can catch preventable problems before the trip.'},{q:'What should you do if a warning suggests an urgent safety problem?',options:['Ignore it until the next year','Stop safely as instructed and seek qualified help','Drive faster to see if it goes away','Post account passwords online'],answer:1,why:'Urgent warnings should be handled using the vehicle guidance and professional support.'}]});

carCourse.lessons.splice(10,0,carCourse.lessons.pop());

